function govSelected(){return $('type').value==='government'}
function govTemplates(){return govTopics.map(([name,desc,questions,category])=>({name,desc,questions,category,l:3,i:4,c:0,hours:160,critical:false,gov:{auditState:'לא ידוע',unresolved:false,materialChange:false}}))}
function govAuditPriority(r){const d=r.gov||{};return Number(d.auditState==='לא בוקר')+Number(Boolean(d.unresolved))+Number(Boolean(d.materialChange))}
function govBoundary(r){const d=r.gov||{},limit=Number(d.limit),target=Number(d.target);return {known:d.limit!==''&&d.limit!==undefined&&Number.isFinite(limit)&&limit>=1&&limit<=25&&Boolean(d.limitApproval?.trim()),exceeds:score(r)>limit,targetAbove:d.target!==''&&d.target!==undefined&&Number.isFinite(target)&&target>limit}}
function govStatus(r){const b=govBoundary(r);return !b.known?'מגבלה מספרית מאושרת טרם תועדה':b.exceeds?'אומדן שיורי מעל המגבלה שתועדה':'אומדן שיורי אינו מעל המגבלה שתועדה'}
function govNextDate(date,years){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return '';const d=new Date(date+'T00:00:00Z');if(Number.isNaN(d.getTime()))return '';d.setUTCFullYear(d.getUTCFullYear()+years);return d.toISOString().slice(0,10)}
function govContextSummary(){return `מנהל סיכונים: ${govContext.manager||'טרם תועד'}; אישור מדיניות אחרון: ${govContext.policyDate||'טרם תועד'}; מועד בקרה שנתי לפי התאריך שהוזן: ${govNextDate(govContext.policyDate,1)||'טרם ניתן לחשב'}; סקר מקיף אחרון: ${govContext.surveyDate||'טרם תועד'}; גבול ארבע השנים לפי התאריך שהוזן: ${govNextDate(govContext.surveyDate,4)||'טרם ניתן לחשב'}. מועד זה אינו היתר לדחות עדכון מהותי, וייתכן צורך בסקר מוקדם יותר.`}
const govProfile=document.createElement('div');govProfile.id='gov-profile';govProfile.className='note';govProfile.hidden=true;
govProfile.innerHTML='<h3>חברה ממשלתית / חברת בת ממשלתית</h3><p>20 תחומי פתיחה מוצעים בהתבסס על החוזר שסופק מ־8.1.2020. הדירוגים והשעות להמחשה ולתיקוף. הבחירה אינה קביעת תחולה.</p><div class="fields"><label>תחולת החוזר<select data-gov-context="scope"><option>טרם נבדק</option><option>נבדק — חל</option><option>נבדק — חברה מנהלת / מבטח מוחרגים</option><option>דרושה חוות דעת</option></select></label><label>מנהל הסיכונים<input data-gov-context="manager" maxlength="200"></label><label>מועד אישור מדיניות אחרון<input type="date" data-gov-context="policyDate"></label><label>מועד סקר מקיף אחרון<input type="date" data-gov-context="surveyDate"></label><label>אסמכתה למדיניות ותיאבון שאושרו<input data-gov-context="policyRef" maxlength="2000"></label><label>תדירות סקר ועדכון דינמי שנקבעה<input data-gov-context="cadence" maxlength="2000"></label><label>הגדרת סולמות והתקופה להערכה<input data-gov-context="scales" maxlength="2000"></label></div><button type="button" id="gov-load">הוספת תחומי חברה ממשלתית חסרים</button><p id="gov-context-status"></p>';
$('form').insertAdjacentElement('afterbegin',govProfile);govProfile.hidden=!govSelected();
$('type').addEventListener('change',()=>govProfile.hidden=!govSelected());
$('form').addEventListener('submit',()=>{if(govSelected()&&!risks.length&&$('form').checkValidity())risks=govTemplates()},true);
$('gov-load').onclick=()=>{govTemplates().forEach(r=>{if(!risks.some(old=>old.name===r.name))risks.push(r)});$('form').requestSubmit()};
govProfile.addEventListener('change',e=>{const key=e.target.dataset.govContext;if(!key)return;govContext[key]=e.target.value;$('gov-context-status').textContent=govContextSummary();if(profile?.type==='government')generate()});
function govField(r,n,key,label){return `<label>${label}<input data-gov-risk="${n}" data-gov-key="${key}" ${govDates.includes(key)?'type="date"':'type="text" maxlength="2000"'} value="${escape(r.gov?.[key]||'')}"></label>`}
function renderGovRegister(){
 let panel=$('gov-register');if(!panel){panel=document.createElement('section');panel.id='gov-register';panel.className='panel';$('survey').insertAdjacentElement('afterend',panel)}
 panel.hidden=profile?.type!=='government';if(panel.hidden)return;
 const opened=[...panel.querySelectorAll('details')].map((d,i)=>d.open?i:-1);
 panel.innerHTML='<h2>מרשם סיכונים לחברה ממשלתית</h2><p>בעלי התהליכים אחראים לניהול החשיפות ותוכניות ההפחתה. שעות הביקורת אינן תקציב ההפחתה. הביקורת בוחנת את ניהול הסיכונים באופן בלתי תלוי.</p><div class="note">סולם 1–5 הוא הצעה שיש לכייל לחברה. אין למצע פגיעה באדם או בשירות חיוני לתוך ציון כספי. מגבלה מספרית 1–25 היא מדד עזר פרטני רק לאחר תיעוד אישור ושיטת המיפוי; אינה תיאבון מצרפי ואינה סכום של ציוני סיכון.</div>'+risks.map((r,n)=>`<details class="ngo-risk"><summary>${escape(r.name)} <span>${escape(govStatus(r))}</span></summary><div class="ngo-risk-body"><p><strong>שאלות לבדיקה:</strong> ${escape(r.questions||'להשלים לפי התהליך')}</p><label>תרחיש — אירוע, סיבה ותוצאה<textarea maxlength="3000" data-gov-risk="${n}" data-gov-key="desc">${escape(r.desc)}</textarea></label><div class="fields"><label>קבוצת סיכון<select data-gov-risk="${n}" data-gov-key="category">${[...govMinimum,'אחר','טרם סווג'].map(v=>`<option ${v===(r.category||'טרם סווג')?'selected':''}>${v}</option>`).join('')}</select></label>${govFields.map(([k,l])=>govField(r,n,k,l)).join('')}<label>מגבלה פרטנית בסולם הציון (1–25)<input type="number" min="1" max="25" step="0.1" data-gov-risk="${n}" data-gov-key="limit" value="${escape(r.gov?.limit??'')}"></label><label>סיכון מטרה בסולם הציון (1–25)<input type="number" min="1" max="25" step="0.1" data-gov-risk="${n}" data-gov-key="target" value="${escape(r.gov?.target??'')}"></label><label>היסטוריית ביקורת<select data-gov-risk="${n}" data-gov-key="auditState">${['לא ידוע','בוקר','לא בוקר'].map(v=>`<option ${r.gov?.auditState===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="ngo-activities">${[['unresolved','ממצאים מהותיים שלא נסגרו'],['materialChange','שינוי מהותי בתהליך'],['critical','קדימות מיוחדת עקב פגיעה חמורה באדם או בשירות חיוני']].map(([k,l])=>`<label><input type="checkbox" data-gov-risk="${n}" data-gov-key="${k}" ${(k==='critical'?r.critical:r.gov?.[k])?'checked':''}>${l}</label>`).join('')}</div><p class="report-disclosure">תעדוף: קדימות מיוחדת, ציון שיורי יורד; בשוויון ציון בלבד, נקודה לכל ״לא בוקר״, ממצא שלא נסגר ושינוי מהותי. תאריך ביקורת וכיסוי גורמי פיקוח מוצגים לשיקול דעת ואינם משוקללים אוטומטית. הציון השיורי עצמו אינו משתנה.</p></div></details>`).join('');
 [...panel.querySelectorAll('details')].forEach((d,i)=>d.open=opened.includes(i));
}
document.addEventListener('change',e=>{const n=e.target.dataset.govRisk,k=e.target.dataset.govKey;if(n===undefined||!k)return;const r=risks[+n];if(!r)return;r.gov??={};if(['limit','target'].includes(k)&&e.target.value!==''&&(!Number.isFinite(+e.target.value)||+e.target.value<1||+e.target.value>25)){e.target.reportValidity();return}if(k==='critical')r.critical=e.target.checked;else if(k==='category')r.category=e.target.value;else if(k==='desc')r.desc=e.target.value;else r.gov[k]=['unresolved','materialChange'].includes(k)?e.target.checked:e.target.value;generate()});
function renderGovRequirements(){
 let panel=$('gov-requirements');if(!panel){panel=document.createElement('section');panel.id='gov-requirements';panel.className='panel';$('gov-register').insertAdjacentElement('afterend',panel)}panel.hidden=profile?.type!=='government';if(panel.hidden)return;
 const opened=[...panel.querySelectorAll('details')].map((d,i)=>d.open?i:-1);
 panel.innerHTML='<h2>מפת דרישות וממשל סיכונים</h2><p>מקור מרכזי: חוזר רשות החברות 2020-13-1 מ־8.1.2020, שנקרא מתוך המסמך שסופק. יש לאמת תחולה, חריגים ועדכונים מול הרשות והיועץ המשפטי. 20 תחומי העבודה המוצעים אינם רשימה שנקבעה במלואה בחוזר.</p>'+govRequirements.map((r,n)=>`<details class="ngo-risk"><summary>${escape(r.topic)} <span>${escape(r.status)}</span></summary><div class="ngo-risk-body"><p><strong>${escape(r.source)}</strong></p><p>${escape(r.check)}</p><div class="fields"><label>מצב בדיקה<select data-gov-requirement="${n}" data-gov-requirement-key="status">${['טרם נבדק','חל — לאחר בדיקה','לא חל — נימוק תועד','דרושה חוות דעת'].map(v=>`<option ${r.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>אחראי<input data-gov-requirement="${n}" data-gov-requirement-key="owner" value="${escape(r.owner)}" maxlength="200"></label><label>אסמכתה, נוסח עדכני ונימוק<input data-gov-requirement="${n}" data-gov-requirement-key="evidence" value="${escape(r.evidence)}" maxlength="2000"></label></div></div></details>`).join('');[...panel.querySelectorAll('details')].forEach((d,i)=>d.open=opened.includes(i));
}
document.addEventListener('change',e=>{const n=e.target.dataset.govRequirement,k=e.target.dataset.govRequirementKey;if(n===undefined||!k)return;govRequirements[+n][k]=e.target.value;generate()});
function renderGovReport(){
 let block=$('gov-report');if(!block){block=document.createElement('div');block.id='gov-report';$('audit-details').insertAdjacentElement('afterend',block)}block.hidden=profile?.type!=='government';if(block.hidden)return;
 const missing=govMinimum.filter(c=>!risks.some(r=>r.category===c));const excess=risks.filter(r=>govBoundary(r).known&&govBoundary(r).exceeds);const unknown=risks.filter(r=>!govBoundary(r).known);const targetAbove=risks.filter(r=>govBoundary(r).known&&govBoundary(r).targetAbove);const uncovered=risks.filter(r=>r.critical&&!alloc.some(y=>y.tasks.includes(r)));
 block.innerHTML=`<h3>נספח חברה ממשלתית: ניהול סיכונים והפחתה</h3><div class="report-gap"><p><strong>תחולת החוזר שהוזנה:</strong> ${escape(govContext.scope)}. ${govContext.scope.includes('מוחרגים')?'מסלול זה משמש מתודולוגיה מוצעת בלבד; אין לייחס לחברה אוטומטית את דרישות חוזר 2020.':''}</p><p>${escape(govContextSummary())}</p><p><strong>מדיניות ותיאבון:</strong> ${escape(govContext.policyRef||'טרם תועדה אסמכתה')}<br><strong>תדירות ועדכון:</strong> ${escape(govContext.cadence||'טרם נקבעו')}<br><strong>הגדרת סולמות:</strong> ${escape(govContext.scales||'טרם תועדה')}</p><p><strong>תחומי מינימום במרשם:</strong> ${missing.length?'חסרים: '+missing.map(escape).join('، '):'כל שבע קבוצות המינימום מופיעות במרשם. הופעתן אינה הוכחה לשלמות או לבדיקה.'}</p><p><strong>מגבלות פרטניות:</strong> ${excess.length} אומדנים מעל מגבלה מספרית שאסמכתה לה תועדה; ${unknown.length} ללא מגבלה מאושרת מתועדת. ${targetAbove.length} סיכוני מטרה מעל המגבלה שתועדה.</p><p><strong>קדימות מיוחדת ללא כיסוי:</strong> ${uncovered.length?uncovered.map(r=>escape(r.name)).join('، '):'לא זוהו תחומים שסומנו ולא שובצו.'}</p><p>השוואת ציונים היא מדד עזר משוער בלבד, לפי שיטת דירוג החברה. אין להסיק שהחשיפה המצרפית עומדת בתיאבון או שהבקרות אפקטיביות.</p></div>`+risks.map(r=>`<article class="audit-card"><h4>${escape(r.name)}</h4><p><strong>קבוצה:</strong> ${escape(r.category||'טרם סווג')} · <strong>שורשי:</strong> ${r.l*r.i} · <strong>שיורי משוער:</strong> ${score(r)} · <strong>מטרה:</strong> ${escape(r.gov?.target||'טרם הוגדרה')} · <strong>מגבלה:</strong> ${escape(r.gov?.limit||'טרם הוגדרה')}</p><p><strong>תרחיש:</strong> ${escape(r.desc)}</p>${govFields.map(([k,l])=>`<p><strong>${l}:</strong> ${escape(r.gov?.[k]||'טרם תועד')}</p>`).join('')}<p><strong>בדיקת מגבלה:</strong> ${escape(govStatus(r))} · <strong>שיקולי ביקורת בשוויון:</strong> ${govAuditPriority(r)}/3; ${escape(r.gov?.auditState||'לא ידוע')}</p><p class="report-disclosure">שעות ביקורת: ${r.hours}; שנת ביקורת: ${alloc.find(y=>y.tasks.includes(r))?.year||'לא שובץ'}. תוכנית ההפחתה באחריות ההנהלה ובעל הסיכון; אינה משימת הביקורת.</p></article>`).join('')+`<h3>בדיקת דרישות</h3><div class="table-wrap"><table><thead><tr><th>נושא / מקור</th><th>מצב</th><th>אחראי ואסמכתה</th></tr></thead><tbody>${govRequirements.map(r=>`<tr><td>${escape(r.topic)}<br>${escape(r.source)}</td><td>${escape(r.status)}</td><td>${escape(r.owner||'טרם הוגדר')}<br>${escape(r.evidence||'טרם תועדה')}</td></tr>`).join('')}</tbody></table></div><p class="report-disclosure">מבוסס על המסמך המצורף מ־8.1.2020. אין כאן אישור לעדכניות כל החוזרים, לתחולה או לעמידה בדין. תוצאות הסקר הן טיוטה לתיקוף בידי החברה.</p>`;
}
const govGenerateBase=generate;generate=function(){govGenerateBase();renderGovRegister();renderGovRequirements();renderGovReport();if(profile.type==='government'){$('gov-context-status').textContent=govContextSummary();$('plan-caption').textContent=`${profile.org} · קדימות מיוחדת, ציון שיורי, ובשוויון ציון שיקולי ביקורת מתועדים. שיבוץ בשנה המוקדמת עם קיבולת; ${profile.reserve}% רזרבה.`}};
const govCsvBase=$('csv').onclick;
$('csv').onclick=()=>{if(profile.type!=='government'){govCsvBase();return}const rows=[['טיוטת סקר לחברה ממשלתית',profile.org],['מקור','חוזר רשות החברות 2020-13-1 מ־8.1.2020; יש לאמת תחולה ועדכונים'],...Object.entries(govContext).map(([k,v])=>[({scope:'תחולת החוזר',manager:'מנהל סיכונים',policyDate:'אישור מדיניות אחרון',surveyDate:'סקר מקיף אחרון',policyRef:'אסמכתת מדיניות ותיאבון',cadence:'תדירות ועדכון',scales:'הגדרת סולמות'})[k],v]),[],['תחום','תרחיש','קבוצה','סבירות','חומרה','שורשי','בקרות','שיורי משוער','מגבלה','סיכון מטרה','מצב מגבלה','קדימות מיוחדת','שיקולי ביקורת בשוויון',...govFields.map(f=>f[1]),'שעות ביקורת','שנת ביקורת']];risks.forEach(r=>rows.push([r.name,r.desc,r.category||'',r.l,r.i,r.l*r.i,controlNames[r.c],score(r),r.gov?.limit||'',r.gov?.target||'',govStatus(r),r.critical?'כן':'לא',govAuditPriority(r),...govFields.map(([k])=>r.gov?.[k]||''),r.hours,alloc.find(y=>y.tasks.includes(r))?.year||'לא שובץ']));rows.push([],['מפת דרישות'],['נושא','מקור','בדיקה','מצב','אחראי','אסמכתה']);govRequirements.forEach(r=>rows.push([r.topic,r.source,r.check,r.status,r.owner,r.evidence]));const safe=v=>{const s=String(v??'');return '"'+(/^[=+@\-\t\r]/.test(s)?"'"+s:s).replaceAll('"','""')+'"'};const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(row=>row.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='government-risk-register.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
